      "rationale": {
        "observation": "The retrieved UAE text defines Data Breach but contains no fixed time period for controller notification to the Bureau.",
        "rule": "A deadline is needed to ensure timely regulatory response and mitigation.",
        "inference": "This is a no_deadline gap in the retrieved UAE data protection regime."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0003",
          "quote": "Data Breach: Breaching information security and Personal Data through illegal or unauthorized access. This includes copying, sending, distributing, exchanging, transferring, circulating or processing it in a way which leads to disclosure of such data to third parties, or destroying or modifying it during storage, transfer and processing"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0187",
          "quote": "The processor shall notify the controller without undue delay after becoming aware of a personal data breach."
